package com.personal.finance;

import java.time.LocalDate;
import java.util.Scanner;

public class MainApp {
    private static UserService userService = new UserService();
    private static FinanceService financeService = new FinanceService();
    private static Scanner scanner = new Scanner(System.in);
    private static User currentUser = null;

    public static void main(String[] args) {
        System.out.println("=== 个人财务管理系统 ===");
        showMainMenu();
    }

    private static void showMainMenu() {
        while (true) {
            System.out.println("\n主菜单:");
            System.out.println("1. 注册");
            System.out.println("2. 登录");
            System.out.println("3. 退出");
            System.out.print("请选择: ");

            int choice = scanner.nextInt();
            scanner.nextLine(); // 消耗换行符

            switch (choice) {
                case 1:
                    registerUser();
                    break;
                case 2:
                    loginUser();
                    break;
                case 3:
                    System.out.println("感谢使用，再见！");
                    System.exit(0);
                default:
                    System.out.println("无效选择，请重试。");
            }
        }
    }

    private static void registerUser() {
        System.out.print("输入用户名: ");
        String username = scanner.nextLine();
        System.out.print("输入邮箱: ");
        String email = scanner.nextLine();
        System.out.print("输入密码: ");
        String password = scanner.nextLine();

        if (userService.register(username, email, password)) {
            System.out.println("注册成功！");
        } else {
            System.out.println("用户名已存在，注册失败。");
        }
    }

    private static void loginUser() {
        System.out.print("输入用户名: ");
        String username = scanner.nextLine();
        System.out.print("输入密码: ");
        String password = scanner.nextLine();

        currentUser = userService.login(username, password);
        if (currentUser != null) {
            System.out.println("登录成功！");
            showFinanceMenu();
        } else {
            System.out.println("用户名或密码错误。");
        }
    }

    private static void showFinanceMenu() {
        while (true) {
            System.out.println("\n财务菜单:");
            System.out.println("1. 添加交易记录");
            System.out.println("2. 查看财务概览");
            System.out.println("3. 查看支出分类统计");
            System.out.println("4. 查看所有交易记录");
            System.out.println("5. 返回主菜单");
            System.out.print("请选择: ");

            int choice = scanner.nextInt();
            scanner.nextLine(); // 消耗换行符

            switch (choice) {
                case 1:
                    addTransaction();
                    break;
                case 2:
                    showFinancialOverview();
                    break;
                case 3:
                    showExpenseByCategory();
                    break;
                case 4:
                    showAllTransactions();
                    break;
                case 5:
                    currentUser = null;
                    return;
                default:
                    System.out.println("无效选择，请重试。");
            }
        }
    }

    private static void addTransaction() {
        System.out.print("金额: ");
        double amount = scanner.nextDouble();
        scanner.nextLine();
        System.out.print("日期(YYYY-MM-DD): ");
        String dateStr = scanner.nextLine();
        LocalDate date = LocalDate.parse(dateStr);
        System.out.print("分类: ");
        String category = scanner.nextLine();
        System.out.print("类型(INCOME/EXPENSE): ");
        String type = scanner.nextLine().toUpperCase();
        System.out.print("描述: ");
        String description = scanner.nextLine();

        financeService.addTransaction(amount, date, category, type, description);
        System.out.println("交易记录添加成功！");
    }

    private static void showFinancialOverview() {
        System.out.println("\n财务概览:");
        System.out.printf("总收入: %.2f\n", financeService.getTotalIncome());
        System.out.printf("总支出: %.2f\n", financeService.getTotalExpense());
        System.out.printf("当前结余: %.2f\n", financeService.getBalance());
    }

    private static void showExpenseByCategory() {
        System.out.println("\n支出分类统计:");
        financeService.getExpenseByCategory().forEach((category, amount) ->
            System.out.printf("%s: %.2f\n", category, amount));
    }

    private static void showAllTransactions() {
        System.out.println("\n所有交易记录:");
        financeService.getAllTransactions().forEach(t ->
            System.out.printf("%s | %s | %s | %.2f | %s\n",
                t.getDate(), t.getType(), t.getCategory(), t.getAmount(), t.getDescription()));
    }
}

